/**
 * Geist Variable TTF, encoded as base64.
 *
 * Bundled here so the workerd OG image wrapper can ship
 * a default font (the wasm renderer does not embed any, unlike native
 * `@takumi-rs/core`). Geist mirrors what the native flavor uses, so OG
 * images look the same across runtimes. The variable axis covers weights
 * 100–900 in a single ~165 KB file.
 *
 * Sourced from https://cdn.jsdelivr.net/npm/geist@latest/dist/fonts/geist-sans/Geist-Variable.ttf
 * (Geist is licensed under the SIL Open Font License 1.1; see
 * https://github.com/vercel/geist-font).
 *
 * NOTE: kept as a single unbroken string literal — babel's traverse
 * stack-overflows on long `+`-concatenated chains.
 */

export const GEIST_VARIABLE_TTF_BASE64 =
  "";
